41	function getActivePopups(int $popupType, int $limit = 50): array
42	{
43	    $limit = max(1, min(500, (int) $limit));
44	
45	    $sql = '
46	        SELECT id, title, popup_type, is_active, start_at, end_at, description,
47	               has_link, link_url, popup_image, sort_no, is_unlimited, is_target
48	        FROM nb_popups
49	        WHERE is_active = 1
50	          AND popup_type = :popup_type
51	          AND (
52	                is_unlimited = 1
53	                OR (
54	                    NULLIF(TRIM(start_at), \'\') IS NOT NULL
55	                    AND NULLIF(TRIM(end_at), \'\') IS NOT NULL
56	                    AND CURDATE() BETWEEN DATE(start_at) AND DATE(end_at)
57	                )
58	          )
59	        ORDER BY sort_no ASC, id DESC
60	        LIMIT :limit
61	    ';
62	
63	    try {
64	        $db = DB::getInstance();
65	        $stmt = $db->prepare($sql);
66	        $stmt->bindValue(':popup_type', $popupType, PDO::PARAM_INT);
67	        $stmt->bindValue(':limit', $limit, PDO::PARAM_INT);
68	        $stmt->execute();
69	
70	        return $stmt->fetchAll(PDO::FETCH_ASSOC) ?: [];
71	    } catch (Throwable $e) {
72	        return [];
73	    }
