167	// 시간 경과 계산
168	function time_ago($date)
169	{
170	    if (empty($date)) return "No date provided";
171	    $periods = ["초", "분", "시간", "일", "주", "개월", "년", "10년"];
172	    $lengths = [60, 60, 24, 7, 4.35, 12, 10];
173	    $now = time();
174	    $unix_date = strtotime($date);
175	    if (!$unix_date) return "Bad date";
176	
177	    $tense = $now > $unix_date ? "전" : "후";
178	    $difference = abs($now - $unix_date);
179	
180	    for ($j = 0; $difference >= $lengths[$j] && $j < count($lengths) - 1; $j++) {
181	        $difference /= $lengths[$j];
182	    }
183	    $difference = round($difference);
184	
185	    return "$difference{$periods[$j]} $tense";
186	}
